use dioxus::prelude::*;
use ui::{
    AppHeader, Blog, Home, InsightsView, MoodTrackerView,
    LandingPage, LoginForm, RegisterForm, AuthContext,
    ProviderDashboard, PatientDetailView,
    AnalyticsDashboard,
};

#[derive(Debug, Clone, Routable, PartialEq)]
#[rustfmt::skip]
pub enum Route {
    // Phase 1: Authentication Routes (no layout)
    #[route("/")]
    Landing,

    #[route("/login")]
    Login,

    #[route("/register")]
    Register,

    // Protected Routes (with layout)
    #[layout(WebLayout)]
        #[route("/dashboard")]
        Home,

        #[route("/blog/:id")]
        Blog { id: i32 },

        #[route("/patients")]
        MoodTrackerView,

        #[route("/analytics")]
        AnalyticsRoute,

        #[route("/insights")]
        InsightsView,

        #[route("/provider/dashboard")]
        ProviderDashboardRoute,

        #[route("/provider/patients/:id")]
        ProviderPatientDetailRoute { id: String },
    #[end_layout]

    // Catch-all route for 404s
    #[route("/:..segments")]
    NotFound { segments: Vec<String> },
}

pub const FAVICON: Asset = asset!("/assets/favicon.ico");
pub const MAIN_CSS: Asset = asset!("/assets/main.css");
pub const REPLICA_CSS: Asset = asset!("/assets/replica.css");
pub const COMPONENTS_CSS: Asset = asset!("/assets/components.css");
pub const DASHBOARD_CSS: Asset = asset!("/assets/dashboard.css");
pub const ANALYTICS_CSS: Asset = asset!("/assets/analytics.css");

#[component]
pub fn App() -> Element {
    // Initialize auth context
    let mut auth_context = use_context_provider(|| AuthContext::new());

    use_effect(move || {
        spawn(async move {
            auth_context.init().await;
        });
    });

    rsx! {
        document::Link { rel: "icon", href: FAVICON }
        document::Link { rel: "stylesheet", href: MAIN_CSS }
        document::Link { rel: "stylesheet", href: REPLICA_CSS }
        document::Link { rel: "stylesheet", href: COMPONENTS_CSS }
        document::Link { rel: "stylesheet", href: DASHBOARD_CSS }
        document::Link { rel: "stylesheet", href: ANALYTICS_CSS }

        Router::<Route> {}
    }
}

// Phase 1: Authentication route components
#[component]
fn Landing() -> Element {
    rsx! { LandingPage {} }
}

#[component]
fn Login() -> Element {
    rsx! { LoginForm {} }
}

#[component]
fn Register() -> Element {
    rsx! { RegisterForm {} }
}

/// Web-specific layout with AppHeader navigation
#[component]
fn WebLayout() -> Element {
    rsx! {
        AppHeader {
            Link { to: Route::Home, "Dashboard" }
            Link { to: Route::MoodTrackerView, "Patients" }
            Link { to: Route::InsightsView, "Analytics" }
        }
        Outlet::<Route> {}
    }
}

// Phase 3: Analytics Routes
#[component]
fn AnalyticsRoute() -> Element {
    rsx! { AnalyticsDashboard {} }
}

// Phase 2: Provider Dashboard Routes
#[component]
fn ProviderDashboardRoute() -> Element {
    rsx! { ProviderDashboard {} }
}

#[component]
fn ProviderPatientDetailRoute(id: String) -> Element {
    rsx! { PatientDetailView { patient_id: id } }
}

#[component]
fn NotFound(segments: Vec<String>) -> Element {
    rsx! {
        div { class: "not-found",
            h1 { "404 - Page Not Found" }
            p { "The page you're looking for doesn't exist: /{segments.join(\"/\")}" }
            Link { to: Route::Landing, "Go to Home" }
        }
    }
}

