use dioxus::prelude::*;
use api::{get_moods_in_range, get_statistics, get_insights, record_mood, MoodEntry, MoodLevel};
use chrono::{Local, Duration, Utc};
use crate::context::use_auth;
use crate::components::{Button, Card, ButtonVariant};

#[component]
pub fn IndividualDashboard() -> Element {
    let auth = use_auth();
    let navigator = use_navigator();

    // Get session_id, or redirect to login if not authenticated
    let session_id = match auth.session_id() {
        Some(id) => id,
        None => {
            // Redirect to login
            use_effect(move || {
                navigator.push("/login");
            });
            return rsx! { div { "Redirecting to login..." } };
        }
    };

    // State
    let mut recent_moods = use_signal(|| Vec::<MoodEntry>::new());
    let mut statistics = use_signal(|| None::<api::analytics::statistics::Statistics>);
    let mut insights = use_signal(|| Vec::<api::analytics::insights::Insight>::new());
    let mut is_loading = use_signal(|| true);
    let mut refresh_trigger = use_signal(|| 0);

    // Clone session_id for use in effects
    let session_id_for_effect = session_id.clone();
    let session_id_for_entry = session_id.clone();

    // Fetch data on mount and when refresh_trigger changes
    use_effect(move || {
        let session_id = session_id_for_effect.clone();
        let _ = refresh_trigger(); // Subscribe to refresh trigger

        spawn(async move {
            is_loading.set(true);
            let end = Utc::now();
            let start = end - Duration::days(7);

            // Fetch recent moods (last 7 days)
            if let Ok(moods) = get_moods_in_range(
                session_id.clone(),
                start,
                end,
            ).await {
                recent_moods.set(moods);
            }

            // Fetch statistics
            if let Ok(stats) = get_statistics(
                session_id.clone(),
                "7d".to_string(),
            ).await {
                statistics.set(Some(stats));
            }

            // Fetch insights
            if let Ok(insights_data) = get_insights(
                session_id.clone(),
            ).await {
                insights.set(insights_data);
            }

            is_loading.set(false);
        });
    });

    let handle_mood_submitted = move |_| {
        refresh_trigger.set(refresh_trigger() + 1);
    };


    if is_loading() {
        return rsx! {
            div { class: "loading-screen",
                "Loading your dashboard..."
            }
        };
    }

    rsx! {
        div { class: "dashboard individual-dashboard",
            // Hero Section - Quick Mood Entry
            section { class: "hero-section",
                Card {
                    class: "quick-mood-card",
                    h2 { "How are you feeling today?" }
                    QuickMoodEntry {
                        session_id: session_id_for_entry.clone(),
                        on_submit: handle_mood_submitted,
                    }
                }
            }

            // Statistics Row
            section { class: "stats-section",
                h3 { "Your Stats (Last 7 Days)" }

                div { class: "stats-grid",
                    if let Some(stats) = statistics() {
                        StatCard {
                            icon: "📊",
                            label: "Average Mood",
                            value: format!("{:.1}", stats.average_mood),
                            trend: None,
                        }
                        StatCard {
                            icon: "🌟",
                            label: "Best Day",
                            value: stats.best_day
                                .map(|d| d.with_timezone(&Local).format("%b %d").to_string())
                                .unwrap_or("N/A".to_string()),
                            trend: None,
                        }
                        StatCard {
                            icon: "📈",
                            label: "Entries",
                            value: format!("{}", stats.total_entries),
                            trend: None,
                        }
                        StatCard {
                            icon: "📝",
                            label: "Most Common",
                            value: stats.mode_mood.label().to_string(),
                            trend: None,
                        }
                    } else {
                        div { class: "empty-state",
                            "No statistics available yet. Start tracking your mood!"
                        }
                    }
                }
            }

            // Mood Trend Chart Placeholder
            section { class: "chart-section",
                Card {
                    h3 { "Mood Trend" }
                    div { class: "chart-placeholder",
                        style: "height: 300px; display: flex; align-items: center; justify-content: center; background: var(--bg-secondary); border-radius: var(--radius-md);",
                        p { style: "color: var(--text-secondary);",
                            "Chart visualization coming in Phase 3"
                        }
                    }
                }
            }

            // Recent Entries
            section { class: "recent-section",
                Card {
                    div { class: "card-header",
                        h3 { "Recent Entries" }
                    }

                    {
                        let recent_moods_read = recent_moods.read();
                        if recent_moods_read.is_empty() {
                            rsx! {
                                div { class: "empty-state",
                                    p { "No mood entries yet. Record your first mood above!" }
                                }
                            }
                        } else {
                            rsx! {
                                div { class: "recent-moods-list",
                                    for mood in recent_moods_read.iter().take(5) {
                                        div {
                                            key: "{mood.id}",
                                            class: "mood-entry-card",
                                            div { class: "mood-entry-content",
                                                div {
                                                    class: "mood-emoji",
                                                    style: "color: {mood.mood.color()}; font-size: 2rem;",
                                                    "{mood.mood.emoji()}"
                                                }

                                                div { class: "mood-details",
                                                    div { class: "mood-info",
                                                        span { class: "mood-label", "{mood.mood.label()}" }
                                                        span {
                                                            class: "mood-time",
                                                            {
                                                                let timestamp = mood.timestamp.with_timezone(&Local);
                                                                let now = Local::now();
                                                                let duration = now.signed_duration_since(timestamp);
                                                                if duration.num_seconds() < 60 {
                                                                    "Just now".to_string()
                                                                } else if duration.num_minutes() < 60 {
                                                                    format!("{}m ago", duration.num_minutes())
                                                                } else if duration.num_hours() < 24 {
                                                                    format!("{}h ago", duration.num_hours())
                                                                } else if duration.num_days() < 7 {
                                                                    format!("{}d ago", duration.num_days())
                                                                } else {
                                                                    timestamp.format("%b %d, %Y").to_string()
                                                                }
                                                            }
                                                        }
                                                    }

                                                    if let Some(notes) = &mood.notes {
                                                        p { class: "mood-notes", "{notes}" }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Insights Widget
            section { class: "insights-section",
                Card {
                    h3 { "💡 Insights & Recommendations" }

                    if insights().is_empty() {
                        p { class: "empty-state",
                            "Track more moods to get personalized insights!"
                        }
                    } else {
                        div { class: "insights-list",
                            for insight in insights().iter().take(3) {
                                div {
                                    key: "{insight.id}",
                                    class: "insight-card",
                                    div {
                                        class: "insight-icon",
                                        {match insight.insight_type {
                                            api::analytics::insights::InsightType::TrendObservation => "📈",
                                            api::analytics::insights::InsightType::CorrelationDiscovery => "🔗",
                                            api::analytics::insights::InsightType::StreakAchievement => "🔥",
                                            api::analytics::insights::InsightType::PatternIdentification => "🔍",
                                            api::analytics::insights::InsightType::Milestone => "🎯",
                                            api::analytics::insights::InsightType::Recommendation => "💡",
                                        }}
                                    }
                                    div { class: "insight-content",
                                        h4 { "{insight.title}" }
                                        p { "{insight.description}" }
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Quick Actions
            section { class: "actions-section",
                h3 { "Quick Actions" }

                div { class: "actions-grid",
                    ActionCard {
                        icon: "📊",
                        title: "View Analytics",
                        description: "Deep dive into your patterns",
                        onclick: move |_| {
                            navigator.push("/analytics");
                        }
                    }
                    ActionCard {
                        icon: "📓",
                        title: "Journal Entry",
                        description: "Write about your day",
                        onclick: move |_| {
                            navigator.push("/journal/new");
                        }
                    }
                    ActionCard {
                        icon: "⚙️",
                        title: "Settings",
                        description: "Manage your preferences",
                        onclick: move |_| {
                            navigator.push("/settings");
                        }
                    }
                }
            }
        }
    }
}

#[component]
fn QuickMoodEntry(session_id: String, on_submit: EventHandler<()>) -> Element {
    let mut selected_mood = use_signal(|| None::<MoodLevel>);
    let mut notes = use_signal(|| String::new());
    let mut is_submitting = use_signal(|| false);
    let mut error_message = use_signal(|| None::<String>);

    let handle_submit = move |_| {
        if let Some(mood) = selected_mood() {
            let session_id = session_id.clone();
            let notes_val = notes();

            spawn(async move {
                is_submitting.set(true);
                error_message.set(None);

                match record_mood(
                    session_id,
                    mood,
                    if notes_val.is_empty() { None } else { Some(notes_val) },
                ).await {
                    Ok(_) => {
                        selected_mood.set(None);
                        notes.set(String::new());
                        on_submit.call(());
                    }
                    Err(e) => {
                        error_message.set(Some(format!("Failed to record mood: {}", e)));
                    }
                }

                is_submitting.set(false);
            });
        }
    };

    rsx! {
        div { class: "quick-mood-entry",
            // Mood selector (horizontal)
            div { class: "mood-selector-inline",
                for mood in [MoodLevel::VeryHappy, MoodLevel::Happy, MoodLevel::Neutral, MoodLevel::Sad, MoodLevel::VerySad] {
                    button {
                        key: "{mood.label()}",
                        class: if selected_mood() == Some(mood) { "mood-button selected" } else { "mood-button" },
                        onclick: move |_| selected_mood.set(Some(mood)),

                        div {
                            class: "mood-emoji",
                            style: "font-size: 2rem; color: {mood.color()};",
                            "{mood.emoji()}"
                        }
                        span { class: "mood-label", "{mood.label()}" }
                    }
                }
            }

            // Optional notes
            if selected_mood().is_some() {
                textarea {
                    class: "notes-input",
                    placeholder: "Add a note (optional)...",
                    value: "{notes()}",
                    oninput: move |evt| notes.set(evt.value()),
                    rows: 2,
                }

                if let Some(error) = error_message() {
                    div { class: "error-message",
                        style: "color: var(--danger); margin: 0.5rem 0;",
                        "{error}"
                    }
                }

                Button {
                    variant: ButtonVariant::Primary,
                    onclick: handle_submit,
                    loading: is_submitting(),
                    disabled: is_submitting(),
                    "Record Mood"
                }
            }
        }
    }
}

#[component]
fn StatCard(
    icon: &'static str,
    label: &'static str,
    value: String,
    trend: Option<String>,
) -> Element {
    rsx! {
        Card {
            class: "stat-card",
            div { class: "stat-icon", "{icon}" }
            div { class: "stat-content",
                div { class: "stat-label", "{label}" }
                div { class: "stat-value", "{value}" }
                if let Some(trend_text) = trend {
                    div {
                        class: "stat-trend {trend_class(&trend_text)}",
                        "{trend_indicator(&trend_text)} {trend_text}"
                    }
                }
            }
        }
    }
}

fn trend_class(trend: &str) -> &'static str {
    if trend.contains("improv") { "positive" }
    else if trend.contains("declin") { "negative" }
    else { "neutral" }
}

fn trend_indicator(trend: &str) -> &'static str {
    if trend.contains("improv") { "↑" }
    else if trend.contains("declin") { "↓" }
    else { "→" }
}

#[component]
fn ActionCard(
    icon: &'static str,
    title: &'static str,
    description: &'static str,
    onclick: EventHandler<()>,
) -> Element {
    rsx! {
        button {
            class: "action-card",
            onclick: move |_| onclick.call(()),

            div { class: "action-icon", "{icon}" }
            h4 { "{title}" }
            p { "{description}" }
        }
    }
}

