#[component]
pub fn ProviderDashboard() -> Element {
    let _auth = use_auth();
    let navigator = use_navigator();

    // TODO: Phase 4 - Replace with actual server function call: list_patients(session_id)
    let patients = use_signal(|| get_mock_patients());
    let is_loading = use_signal(|| false);
    let mut filter = use_signal(|| PatientFilter::All);

    // Calculate high-risk patients
    let high_risk_patients = use_memo(move || {
        patients.read().iter()
            .filter(|p| matches!(p.risk_level, MockRiskLevel::High | MockRiskLevel::Critical))
            .cloned()
            .collect::<Vec<_>>()
    });

    // Filter patients based on selection
    let filtered_patients = use_memo(move || {
        let filter_val = filter.read().clone();
        let all_patients = patients.read().clone();

        match filter_val {
            PatientFilter::All => all_patients,
            PatientFilter::HighRisk => all_patients.into_iter()
                .filter(|p| matches!(p.risk_level, MockRiskLevel::High | MockRiskLevel::Critical))
                .collect(),
            PatientFilter::Recent => {
                // For now, just return first 10
                all_patients.into_iter().take(10).collect()
            }
