#[component]
fn StatCard(
    icon: &'static str,
    label: &'static str,
    value: String,
    trend: Option<String>,
) -> Element {
    rsx! {
        Card {
            class: "stat-card",
            div { class: "stat-icon", "{icon}" }
            div { class: "stat-content",
                div { class: "stat-label", "{label}" }
                div { class: "stat-value", "{value}" }
                if let Some(trend_text) = trend {
                    div {
                        class: format!("stat-trend {}", trend_class(&trend_text)),
                        "{trend_indicator(&trend_text)} {trend_text}"
                    }
                }
            }
        }
    }
}

#[component]
pub fn RiskBadge(level: MockRiskLevel) -> Element {
    let (text, variant) = match level {
        MockRiskLevel::Low => ("Low", BadgeVariant::Success),
        MockRiskLevel::Moderate => ("Moderate", BadgeVariant::Warning),
        MockRiskLevel::High => ("High", BadgeVariant::Danger),
        MockRiskLevel::Critical => ("Critical", BadgeVariant::Danger),
    };

    rsx! {
        Badge {
            variant: variant,
            class: "risk-badge",
            "{text}"
        }
    }
}

fn trend_class(trend: &str) -> &'static str {
    if trend.contains("improv") { "positive" }
    else if trend.contains("declin") { "negative" }
    else { "neutral" }
}

fn trend_indicator(trend: &str) -> &'static str {
    if trend.contains("improv") { "↑" }
    else if trend.contains("declin") { "↓" }
    else { "→" }
}

fn calculate_avg_trend(patients: &[MockPatient]) -> String {
    if patients.is_empty() {
        return "N/A".to_string();
    }

    let total: f64 = patients.iter()
        .filter_map(|p| p.avg_mood)
        .sum();

    let count = patients.iter().filter(|p| p.avg_mood.is_some()).count();
    if count == 0 {
        return "N/A".to_string();
    }

    let avg = total / count as f64;
    format!("{:.1}", avg)
}

fn count_active_today(patients: &[MockPatient]) -> usize {
    // For mock data, just count those checked in recently
    patients.iter()
        .filter(|p| p.last_check_in.contains("ago") && !p.last_check_in.contains("day"))
        .count()
}

fn format_relative_time(timestamp: &str) -> String {
    // For mock data, just return as-is since it's already formatted
    timestamp.to_string()
}

