mod tests {
    use web::Route;
    use dioxus::prelude::*;
    use std::str::FromStr;

    #[test]
    fn test_codebase_routes() {
        let paths_to_check = vec![
            "/",
            "/login",
            "/register",
            "/dashboard",
            "/provider/dashboard",
            "/analytics",
            "/insights", // from WebLayout
            "/patients", // from WebLayout
            // "/journal/new", // added
            // "/settings", // added
            // "/provider/patients/:id" - Need to test instantiation
        ];

        for path in paths_to_check {
            let route = Route::from_str(path);
            if route.is_err() || matches!(route.unwrap(), Route::NotFound { .. }) {
                println!("Failed to parse known static route: {}", path);
                panic!("Route failure: {}", path);
            }
        }

        // Test dynamic routes
        let provider_patient = Route::from_str("/provider/patients/123");
        assert!(matches!(provider_patient.unwrap(), Route::ProviderPatientDetailRoute { id } if id == "123"));

        let blog = Route::from_str("/blog/1");
         assert!(matches!(blog.unwrap(), Route::Blog { id } if id == 1));
    }
}

