use dioxus::prelude::*;
use crate::components::Card;
use crate::components::dashboard::provider_dashboard::{MockPatient, RiskBadge};

#[component]
pub fn PatientCard(patient: MockPatient) -> Element {
    let navigator = use_navigator();

    rsx! {
        div {
            class: "patient-card-link",
            onclick: move |_| {
                let id = patient.id.clone();
                navigator.push(format!("/provider/patients/{}", id));
            },

            Card {
                class: format!("patient-card risk-{}", patient.risk_level.to_string()),

                div { class: "patient-header",
                    div { class: "patient-avatar",
                        {patient.name.chars().next().unwrap_or('?').to_uppercase().to_string()}
                    }

                    div { class: "patient-info",
                        h4 { class: "patient-name", "{patient.name}" }
                        span { class: "patient-id", "ID: {&patient.id}" }
                    }

                    RiskBadge { level: patient.risk_level }
                }

                div { class: "patient-stats",
                    div { class: "stat-item",
                        span { class: "stat-label", "Last Check-in" }
                        span { class: "stat-value", "{format_relative_time(&patient.last_check_in)}" }
                    }

                    if let Some(avg_mood) = patient.avg_mood {
                        div { class: "stat-item",
                            span { class: "stat-label", "Avg Mood" }
                            span { class: "stat-value", "{avg_mood:.1}" }
                        }
                    }

                    div { class: "stat-item",
                        span { class: "stat-label", "Trend" }
                        span {
                            class: format!("stat-value trend-{}", trend_class(&patient.trend.as_ref().unwrap_or(&"stable".to_string()))),
                            "{trend_indicator(&patient.trend.as_ref().unwrap_or(&\"stable\".to_string()))} {patient.trend.as_ref().unwrap_or(&\"Stable\".to_string())}"
                        }
                    }
                }

                if let Some(alert) = &patient.latest_alert {
                    div { class: "patient-alert",
                        "💬 {alert}"
                    }
                }
            }
        }
    }
}

fn trend_class(trend: &str) -> &'static str {
    if trend.contains("improv") { "positive" }
    else if trend.contains("declin") { "negative" }
    else { "neutral" }
}

fn trend_indicator(trend: &str) -> &'static str {
    if trend.contains("improv") { "↑" }
    else if trend.contains("declin") { "↓" }
    else { "→" }
}

fn format_relative_time(timestamp: &str) -> String {
    // For mock data, timestamp is already formatted
    timestamp.to_string()
}

